data: {"index":1,"delta":{"text":"### Causes of the French Revolution\n\nThe revolution did not happen overnight; it was the result of a convergence of economic, social, intellectual","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":", and political pressures that built up over decades.\n\n**1. Social Inequality and the Estates System**\nPre-revolutionary","type":"text"},"event_type":"step.delta"}

